/* 任务日历与列表共用 CULTIVATION_PROJECTS 中的任务。 */
(() => {
'use strict';
const page=document.getElementById('page-tasks');if(!page)return;
const e=orderEscape,today=cultivationTaskToday(),colors=['#2563eb','#7c3aed','#0891b2','#059669','#d97706','#db2777','#4f46e5'];
const valid=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')&&Number.isFinite(Date.parse(s+'T12:00:00Z'));
function addDays(s,n){const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function workDay(s,n){let day=s;while(n>0){day=addDays(day,1);if(![0,6].includes(new Date(day+'T12:00:00Z').getUTCDay()))n--;}while([0,6].includes(new Date(day+'T12:00:00Z').getUTCDay()))day=addDays(day,1);return day;}
const state={view:'calendar',month:today.slice(0,7),selected:null,filtered:[],all:[]};
function execution(t){return valid(t.scheduledDate)?t.scheduledDate:valid(t.deadline)?t.deadline:'';}
function color(t){return colors[Math.max(0,Array.from(CULTIVATION_PROJECTS.values()).findIndex(p=>p.id===t.projectId))%colors.length];}
// 仅给现有演示项目的未排期任务生成示例排期，新加入的任务采用用户确认的安排。
if(!window.NEW_USER)Array.from(CULTIVATION_PROJECTS.values()).forEach((p,pi)=>p.tasks.forEach((t,i)=>{if(!execution(t)){t.scheduledDate=workDay(addDays(today,p.status==='已完成'?-15:-3),(pi*2+i)%15);t.deadline=workDay(t.scheduledDate,2);t.scheduleSource='示例排期';}else if(!t.scheduledDate)t.scheduledDate=t.deadline;}));
const toolbar=document.createElement('div');toolbar.className='tc-toolbar';toolbar.innerHTML='<div class="tc-view-toggle" role="group" aria-label="任务视图"><button type="button" data-task-view="list">列表视图</button><button type="button" data-task-view="calendar">日历视图</button></div><div class="tc-month-controls"><button type="button" data-task-month="-1" aria-label="上个月">‹</button><b id="tc-month-label"></b><button type="button" data-task-month="1" aria-label="下个月">›</button><button type="button" data-task-today>今天</button></div><button type="button" data-task-clear-day hidden>显示全部日期</button>';
const table=page.querySelector('.cult-task-table-wrap'),calendar=document.createElement('div');calendar.id='task-calendar-view';table.before(toolbar,calendar);table.querySelector('th:nth-child(4)').textContent='?? / ????';
const scheduleDialog=document.createElement('dialog');scheduleDialog.id='task-schedule-dialog';scheduleDialog.innerHTML='<form id="task-schedule-form"><header><div><h3>安排任务</h3><p id="task-schedule-project"></p></div><button type="button" data-schedule-close aria-label="关闭">×</button></header><div class="tc-schedule-body"><p id="task-schedule-name"></p><div id="task-schedule-output"></div><label>执行日期<input type="date" id="task-schedule-date"></label><label>截止日期<input type="date" id="task-schedule-deadline"></label><label>负责人<input id="task-schedule-owner" maxlength="80"></label><label>任务状态<select id="task-schedule-status"><option>待处理</option><option>进行中</option><option>待审核</option><option>已完成</option></select></label><p class="tc-note">不设置执行日期与截止日期时，任务保留在待排期列表。</p></div><footer><button type="button" data-schedule-close>取消</button><button type="submit" class="tc-primary">保存安排</button></footer></form>';page.append(scheduleDialog);
let editing=null;
function refresh(){renderCultivationTasks();}
function taskButton(t){return '<button type="button" class="tc-event '+(t.status==='已完成'?'is-done':'')+'" style="--task-color:'+color(t)+'" data-task-detail="'+e(t.id)+'" title="'+e(t.project+' · '+t.name)+'"><span>'+e(t.name)+'</span><small>'+e(t.project)+'</small></button>';}
function agendaTask(t){return '<article class="tc-agenda-task" style="--task-color:'+color(t)+'"><div><span>'+e(t.status)+'</span><small>'+e(t.scheduleSource||'已安排')+'</small></div><b>'+e(t.name)+'</b><p>'+e(t.project)+'</p><p>负责人：'+e(t.owner||'待分配')+'</p><small>交付：'+e(t.output)+'</small><footer><button type="button" data-task-detail="'+e(t.id)+'">查看任务</button><button type="button" data-task-schedule="'+e(t.id)+'">调整安排</button></footer></article>';}
function render(filtered,all){state.filtered=filtered;state.all=all;
 page.querySelectorAll('[data-task-view]').forEach(b=>{b.classList.toggle('active',b.dataset.taskView===state.view);b.setAttribute('aria-pressed',String(b.dataset.taskView===state.view));});
 table.hidden=state.view!=='list';calendar.hidden=state.view!=='calendar';toolbar.querySelector('.tc-month-controls').hidden=state.view!=='calendar';toolbar.querySelector('[data-task-clear-day]').hidden=!state.selected;
 const [year,month]=state.month.split('-').map(Number);document.getElementById('tc-month-label').textContent=year+'年 '+month+'月';
 const unscheduled=filtered.filter(t=>!execution(t)),displayDay=state.selected||today,dayTasks=filtered.filter(t=>execution(t)===displayDay),monthTasks=filtered.filter(t=>execution(t).startsWith(state.month));
 const first=state.month+'-01',offset=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,start=addDays(first,-offset);
 let cells='';for(let i=0;i<42;i++){const day=addDays(start,i),tasks=filtered.filter(t=>execution(t)===day);cells+='<div class="tc-day '+(day.slice(0,7)!==state.month?'outside ':'')+(day===today?'today ':'')+(day===state.selected?'selected':'')+'"><button type="button" class="tc-day-number" data-task-day="'+day+'" aria-label="查看'+day+'的'+tasks.length+'项任务" '+(day===state.selected?'aria-pressed="true"':'')+'>'+Number(day.slice(-2))+(day===today?'<small>今</small>':'')+'</button>'+tasks.slice(0,3).map(taskButton).join('')+(tasks.length>3?'<button type="button" class="tc-more" data-task-day="'+day+'">另有 '+(tasks.length-3)+' 项</button>':'')+'</div>';}
 const projects=Array.from(new Set(filtered.map(t=>t.project)));calendar.innerHTML='<div class="tc-overview"><span>本月 '+monthTasks.length+' 项任务 · 跨 '+new Set(monthTasks.map(t=>t.project)).size+' 个项目</span><small>点击日期查看当日汇总；示例项目排期可调整</small></div><div class="tc-project-legend">'+projects.map(name=>{const t=filtered.find(t=>t.project===name);return '<span><i style="background:'+color(t)+'"></i>'+e(name)+'</span>';}).join('')+'</div><div class="tc-calendar-layout"><section class="tc-month"><div class="tc-weekdays">'+['一','二','三','四','五','六','日'].map(d=>'<span>周'+d+'</span>').join('')+'</div><div class="tc-grid">'+cells+'</div></section><aside class="tc-agenda"><h3>'+e(displayDay)+' <small>'+dayTasks.length+' 项</small></h3><p>当日跨项目任务</p>'+dayTasks.map(agendaTask).join('')+(dayTasks.length?'':'<div class="tc-empty">当日没有符合筛选条件的任务</div>')+'</aside></div><details class="tc-unscheduled" '+(unscheduled.length?'open':'')+'><summary>待排期任务 · '+unscheduled.length+' 项</summary>'+unscheduled.map(t=>'<div><span><b>'+e(t.name)+'</b><small>'+e(t.project)+' · '+e(t.owner)+'</small></span><button type="button" data-task-schedule="'+e(t.id)+'">安排日期</button></div>').join('')+(!unscheduled.length?'<p>当前筛选范围内没有待排期任务。</p>':'')+'</details>';
 let visibleCount=0;page.querySelectorAll('#cult-task-body tr[data-task-row]').forEach(row=>{const task=filtered.find(t=>t.id===row.dataset.taskRow),date=task?execution(task):'';row.hidden=!!state.selected&&date!==state.selected;if(!row.hidden)visibleCount++;if(task){row.cells[3].innerHTML='<b class="tc-list-date">执行：'+e(date||'待排期')+'</b><small>截止：'+e(task.deadline||'未设置')+'</small>'+(task.scheduleSource?'<small>'+e(task.scheduleSource)+'</small>':'');}});
 const shown=state.selected?filtered.filter(t=>execution(t)===state.selected):filtered;if(filtered.length&&!shown.length){const empty=document.createElement('tr');empty.innerHTML='<td colspan="6" class="cult-task-empty">???????????????????????????????</td>';document.getElementById('cult-task-body').append(empty);}document.getElementById('cult-task-total').textContent='共 '+shown.length+' 项任务 · 来自 '+new Set(shown.map(t=>t.project)).size+' 个培育项目'+(state.selected?' · 执行日期 '+state.selected:'');
}
function openSchedule(id){const found=findCultivationTask(id);if(!found)return;editing=found;const t=found.task;document.getElementById('task-schedule-project').textContent=found.project.name;document.getElementById('task-schedule-name').textContent=t.name;document.getElementById('task-schedule-output').textContent='交付材料：'+t.output+(t.acceptance?'；完成要求：'+t.acceptance:'');document.getElementById('task-schedule-date').value=execution(t);document.getElementById('task-schedule-deadline').value=valid(t.deadline)?t.deadline:'';document.getElementById('task-schedule-owner').value=t.owner||'';document.getElementById('task-schedule-status').value=t.status;document.getElementById('task-schedule-deadline').setCustomValidity('');scheduleDialog.showModal();}
page.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.taskView){state.view=b.dataset.taskView;refresh();}else if(b.hasAttribute('data-task-month')){const d=new Date(state.month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.taskMonth));state.month=d.toISOString().slice(0,7);state.selected=null;refresh();}else if(b.hasAttribute('data-task-today')){state.month=today.slice(0,7);state.selected=today;refresh();}else if(b.dataset.taskDay){state.selected=b.dataset.taskDay;state.month=state.selected.slice(0,7);refresh();}else if(b.hasAttribute('data-task-clear-day')){state.selected=null;refresh();}else if(b.dataset.taskSchedule)openSchedule(b.dataset.taskSchedule);else if(b.dataset.taskDetail)openCultivationTask(b.dataset.taskDetail);});
page.querySelector('#cult-task-reset').addEventListener('click',()=>{state.selected=null;state.month=today.slice(0,7);refresh();});
['task-schedule-date','task-schedule-deadline'].forEach(id=>document.getElementById(id).addEventListener('input',()=>document.getElementById('task-schedule-deadline').setCustomValidity('')));
scheduleDialog.querySelectorAll('[data-schedule-close]').forEach(b=>b.onclick=()=>scheduleDialog.close());
document.getElementById('task-schedule-form').addEventListener('submit',event=>{event.preventDefault();if(!editing)return;const date=document.getElementById('task-schedule-date').value,deadline=document.getElementById('task-schedule-deadline').value,deadlineInput=document.getElementById('task-schedule-deadline');deadlineInput.setCustomValidity(date&&deadline&&deadline<date?'截止日期不能早于执行日期':'');if(!deadlineInput.reportValidity())return;Object.assign(editing.task,{scheduledDate:date,deadline,owner:document.getElementById('task-schedule-owner').value.trim()||'待分配',status:document.getElementById('task-schedule-status').value,scheduleSource:'已确认排期'});state.selected=date||null;if(date)state.month=date.slice(0,7);document.querySelectorAll('#project-list .project-card').forEach(row=>{if(row.dataset.name===editing.project.name&&row.cells?.[3])row.cells[3].textContent=editing.project.tasks.filter(t=>t.status==='???').length+'/'+editing.project.tasks.length;});if(currentCultivationProject?.id===editing.project.id)renderCultivationProjectTasks(editing.project);scheduleDialog.close();refresh();showToast('任务安排已同步到日历和列表','success');});
window.TaskCalendar={render,inspect:()=>({view:state.view,month:state.month,selected:state.selected,tasks:state.all}),addAgentTasks:payload=>addAgentTasks(payload)};
function addAgentTasks(payload){
 const {existing,name,start,schedule,tasks,source}=payload;let project=existing?CULTIVATION_PROJECTS.get(existing):CULTIVATION_PROJECTS.get(name);if(existing&&!project)return null;
 let created=false;if(!project){created=true;project={id:'CP-AI-'+Date.now().toString(36),name,type:'自主',status:'进行中',owner:'待分配',tasks:[]};CULTIVATION_PROJECTS.set(name,project);}
 const duplicate=project.tasks.filter(t=>t.agentSource===source);if(duplicate.length)return {project:project.name,count:duplicate.length};
 const offset=[0,1,2,2,4,7];tasks.forEach((task,i)=>{const date=schedule?workDay(start,offset[i]??(i+1)):'';project.tasks.push({id:project.id+'-AI-'+source.slice(0,8)+'-'+i,projectId:project.id,name:task.title,output:task.output||task.deliverables?.join('、')||'任务交付记录',owner:task.owner||'待分配',status:'待处理',scheduledDate:date,deadline:date?workDay(date,2):'',steps:task.steps||[],acceptance:task.acceptance||'',service:task.service||null,agentSource:source,source:'agent',scheduleSource:schedule?'已确认建议排期':'待排期'});});
 if(created){const row=document.createElement('tr');row.className='project-card';row.dataset.name=project.name;row.dataset.type='自主';row.dataset.status='进行中';row.innerHTML='<td class="px-4 py-3">'+e(project.name)+'</td><td>自主</td><td>进行中</td><td>0/'+project.tasks.length+'</td><td>按任务排期</td><td>待分配</td><td><button type="button" class="u-button ghost">查看任务清单</button></td>';row.querySelector('button').onclick=()=>openDrawer({dataset:{name:project.name,type:'自主',status:'进行中'}});document.querySelector('#project-list tbody').append(row);
 const card=document.createElement('div');card.className='u-project-card cultivation-project-card-v2 project-card';Object.assign(card.dataset,{name:project.name,type:'自主',status:'进行中'});card.innerHTML='<div class="u-tags"><span class="u-chip blue">智能体生成任务</span><span class="u-chip amber">进行中</span></div><h3>'+e(project.name)+'</h3><p>根据本轮企业分析创建，包含 '+project.tasks.length+' 项具体准备任务。</p><div class="u-actions"><button type="button" class="u-button">查看培育任务</button></div>';card.querySelector('button').onclick=row.querySelector('button').onclick;document.getElementById('project-inprogress-list').append(card);document.getElementById('project-inprogress-count').textContent=Array.from(CULTIVATION_PROJECTS.values()).filter(p=>p.status==='进行中').length;
 }else document.querySelectorAll('#project-list .project-card').forEach(row=>{if(row.dataset.name===project.name&&row.cells?.[3])row.cells[3].textContent=project.tasks.filter(t=>t.status==='已完成').length+'/'+project.tasks.length;});
 state.selected=null;state.month=schedule?start.slice(0,7):today.slice(0,7);refresh();return {project:project.name,count:tasks.length};
}
refresh();
})();
